When `chunk_code` is not NULL, input should be unquoted naked expression:
``` r
library(magrittr)
setup_chunk2 <- function (chunk_code = NULL, chunk_args = list(include = FALSE)) 
{
  arg_null <- rlang::enquo(chunk_code) %>% rlang::quo_is_null()
  if (arg_null) {
    code_chunk_txt <- ymlthis::code_chunk(chunk_code = {
      knitr::opts_chunk$set(echo = TRUE)
    }, chunk_name = "setup", chunk_args = !!rlang::enquo(chunk_args))
  }
  else {
    code_chunk_txt <- ymlthis::code_chunk(chunk_code = !!rlang::enexpr(chunk_code),
                                          chunk_name = "setup", chunk_args = !!rlang::enquo(chunk_args))
  }
  code_chunk_txt
}

ymlthis::setup_chunk(chunk_code = 1+1)
#> ```{r setup, include = FALSE}
#> chunk_code
#> ```
setup_chunk2(chunk_code = 1+1)
#> ```{r setup, include = FALSE}
#> 1 + 1
#> ```
```

